//! Every shader the renderer builds: the Slang file, the entry point, the
//! stage and the name of the SPIR-V the renderer loads it by. `build.zig`
//! compiles each; a pass adds its shaders here.
pub const Shader = struct {
    src: []const u8,
    name: []const u8,
    defines: []const []const u8 = &.{},
    /// The entry point to compile and its stage.
    entry: []const u8,
    stage: []const u8,
    /// Skips `spirv_readonly` for a shader whose buffer reads timed faster
    /// on the writable path.
    writable_reads: bool = false,
};

